
fn seeded(n:u64)->sha3::Shake256Reader{let mut h=Shake256::default();h.update(b"fixed-input-rng-anf-validation-v1");h.update(&n.to_le_bytes());h.finalize_xof()}
fn main(){let args:Vec<_>=std::env::args().collect();let ops=load_ops(&args[1]).unwrap();let(nq,nb,_,regs)=analyze_ops(ops.iter());assert!(args.len()>=5,"certified-region summary paths required");let mut ranges=Vec::new();for path in &args[4..]{let summary:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();assert_eq!(summary["full_operation_count"].as_u64().unwrap(),ops.len()as u64);for region in summary["selected_disjoint_certified_regions"].as_array().unwrap(){let start=region[0].as_u64().unwrap()as usize;let end=region[1].as_u64().unwrap()as usize;assert!(start<=end&&end<ops.len()&&end-start<10000);ranges.push((start,end));}}ranges.sort_unstable_by_key(|(a,b)|(*a,std::cmp::Reverse(*b)));ranges.dedup();let mut selected=Vec::new();for(a,b)in ranges{if selected.last().map_or(true,|(_,end)|a>*end){selected.push((a,b));}}let mut skip=vec![false;ops.len()];let mut methods=[0usize;2];for(start,end)in &selected{let span=&ops[*start..=*end];if coeff_projection::prove(span){methods[0]+=1;}else if symbol_projection::prove(span){methods[1]+=1;}else{panic!("selected reset projection did not re-prove: {start}..{end}");}for i in *start..=*end{if matches!(ops[i].kind,OperationType::X|OperationType::CX|OperationType::CCX|OperationType::Swap){skip[i]=true;}}}let removed=skip.iter().filter(|v|**v).count();eprintln!("CERTIFIED_RESET_REWRITE regions={} removed_value_ops={} methods={methods:?}",selected.len(),removed);let reduced:Vec<_>=ops.iter().enumerate().filter(|(i,_)|!skip[*i]).map(|(_,o)|o.clone()).collect();let output=&args[2];let mut file=File::create(format!("{output}.ops.bin")).unwrap();file.write_all(MAGIC).unwrap();file.write_all(&(reduced.len()as u64).to_le_bytes()).unwrap();let mut encoder=zstd::stream::Encoder::new(file,3).unwrap();for o in &reduced{for value in [o.kind as u64,o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]{encoder.write_all(&value.to_le_bytes()).unwrap();}}encoder.finish().unwrap();let compact=Compact::compile(&reduced);let mut file=File::create(format!("{output}.compact16.bin")).unwrap();for o in &compact.ops{file.write_all(&o.a.to_le_bytes()).unwrap();file.write_all(&o.b.to_le_bytes()).unwrap();file.write_all(&o.t.to_le_bytes()).unwrap();file.write_all(&[o.k,0]).unwrap();file.write_all(&o.c.to_le_bytes()).unwrap();file.write_all(&o.bt.to_le_bytes()).unwrap();}let original_mr=ops.iter().filter(|o|matches!(o.kind,OperationType::R|OperationType::Hmr)).count();assert_eq!(original_mr,compact.rng_count);let report=serde_json::json!({"original_stream_for_fiat_transcript":args[1],"never_hash_reduced_program_for_benchmark_inputs_or_rng":true,"original_operation_count":ops.len(),"reduced_operation_count":reduced.len(),"compact_operation_count":compact.ops.len(),"compact_op_bytes":16,"all_original_mr_draw_positions_preserved":true,"mr_events":original_mr,"quantum_wires":nq,"classical_bits":nb,"certified_regions":selected.len(),"proof_methods":methods,"removed_quantum_value_operations":removed,"selected_disjoint_regions":selected,"registers":regs.iter().map(|r|r.iter().map(|w|match w{QubitOrBit::Qubit(id)=>serde_json::json!({"kind":"q","id":id.0}),QubitOrBit::Bit(id)=>serde_json::json!({"kind":"b","id":id.0})}).collect::<Vec<_>>()).collect::<Vec<_>>(),"status":"EXACT_VALUE_ONLY_RESEARCH_IR_PHASE_NOT_PRESERVED"});std::fs::write(format!("{output}.json"),format!("{report}\n")).unwrap();println!("CERTIFIED_IR_EXPORTED prefix={output} regions={} removed={} compact={} mr={original_mr}",selected.len(),removed,compact.ops.len());}
